package mockey

type mockOption struct {
	unsafe  bool
	generic *bool
	method  *bool
}

type mockOptionFn func(*mockOption)

func OptUnsafe(o *mockOption) {
	o.unsafe = true
}

func OptGeneric(o *mockOption) {
	var t = true
	o.generic = &t
}

func OptMethod(o *mockOption) {
	var t = true
	o.method = &t
}

func resolveMockOpt(fn ...mockOptionFn) *mockOption {
	opt := &mockOption{
		unsafe:  false,
		generic: nil,
		method:  nil,
	}
	for _, f := range fn {
		f(opt)
	}
	return opt
}

