func TestVarPatchConvey(t *testing.T) {
	b := 1
	a := 10
	PatchConvey("test mock2", t, func() {
		PatchConvey("test mock3", func() {
			MockValue(&a).To(20)
			So(a, ShouldEqual, 20)
			PatchConvey("test mock4", func() {
				MockValue(&a).To(30)
				MockValue(&b).To(40)
				So(b, ShouldEqual, 40)
				So(a, ShouldEqual, 30)
			})
			So(b, ShouldEqual, 1)
		})
		So(b, ShouldEqual, 1)
		So(a, ShouldEqual, 10)

		PatchConvey("test mock5", func() {
			MockValue(&a).To(30)
			So(a, ShouldEqual, 30)
		})

		So(a, ShouldEqual, 10)
	})
}

type testStruct struct {
