			if value != 3 {
				t.Fatalf("inner value = %d, want 3", value)
			}
		})
		if value != 2 {
			t.Fatalf("value after inner cleanup = %d, want 2", value)
		}
		outer.UnPatch()
		if value != 1 {
			t.Fatalf("value after outer unpatch = %d, want 1", value)
		}
	})
